<div class="body"><section><h2><?= e($content['property_about'] ?? 'Konaklama hakkında') ?></h2><p class="description"><?= e($property['description'] ?: $property['summary'] ?: '') ?></p><?php if(!empty($propertyAmenities)): ?><h3>Bu konaklamanın özellikleri</h3><ul style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding-left:20px"><?php foreach($propertyAmenities as $amenity): ?><li><?= e($amenity['name']) ?></li><?php endforeach; ?></ul><?php endif; ?><?php if(!empty($reviews)): ?><section><h2>Misafir değerlendirmeleri</h2><?php foreach($reviews as $review): ?><article style="border-top:1px solid #e8ece9;padding:14px 0"><strong><?= e($review['username']) ?> · <?= (int)$review['rating'] ?>/5</strong><p><?= e($review['body']) ?></p><small class="muted"><?= e(date('d.m.Y',strtotime($review['created_at']))) ?></small></article><?php endforeach; ?></section><?php endif; ?></section><aside class="booking"><strong><?= e(number_format((float)$property['base_nightly_price'],0,',','.')) ?> <?= e($property['currency']) ?> <span class="muted" style="font-size:14px;font-weight:400">/ gece</span></strong><p>Rezervasyon talebinizi oluşturmak ve müsaitlik bilgisi almak için bizimle iletişime geçebilirsiniz.</p><a href="/villa/<?= e($property['slug']) ?>/reserve"><?= e($content['property_reserve'] ?? 'Rezervasyon talebi gönder') ?></a></aside></div></main><script>(function(){var button=document.querySelector(".mobile-menu-toggle"),menu=document.getElementById("siteNavigation");if(!button||!menu)return;function close(){menu.classList.remove("is-open");button.setAttribute("aria-expanded","false");button.setAttribute("aria-label","Menüyü aç");button.textContent="☰"}button.addEventListener("click",function(){var open=menu.classList.toggle("is-open");button.setAttribute("aria-expanded",open?"true":"false");button.setAttribute("aria-label",open?"Menüyü kapat":"Menüyü aç");button.textContent=open?"×":"☰"});menu.addEventListener("click",function(e){if(e.target.closest("a"))close()});document.addEventListener("keydown",function(e){if(e.key==="Escape")close()});window.addEventListener("resize",function(){if(window.innerWidth>700)close()})})();var galleryImages=<?= json_encode(array_map(static function(array $image):array{return ['src'=>preg_match('~^https?://~i',(string)$image['file_path'])?$image['file_path']:'/'.ltrim($image['file_path'],'/'),'alt'=>$image['alt_text']?:$property['title']];},$images),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) ?>;
(function(){var modal=document.getElementById('photoLightbox');if(!modal||!galleryImages.length)return;var image=document.getElementById('lightboxImage'),counter=document.getElementById('lightboxCounter'),index=0,touchX=0;
function show(n){index=(n+galleryImages.length)%galleryImages.length;image.src=galleryImages[index].src;image.alt=galleryImages[index].alt;counter.textContent=(index+1)+' / '+galleryImages.length}
function open(n){show(n);modal.classList.add('is-open');document.body.style.overflow='hidden';document.getElementById('lightboxClose').focus()}
function close(){modal.classList.remove('is-open');document.body.style.overflow=''}
document.querySelectorAll('[data-gallery-index]').forEach(function(button){button.addEventListener('click',function(){open(Number(button.dataset.galleryIndex))})});
var all=document.getElementById('showAllPhotos');if(all)all.addEventListener('click',function(){open(0)});
document.getElementById('lightboxClose').addEventListener('click',close);document.getElementById('lightboxPrev').addEventListener('click',function(){show(index-1)});document.getElementById('lightboxNext').addEventListener('click',function(){show(index+1)});
modal.addEventListener('click',function(e){if(e.target===modal)close()});document.addEventListener('keydown',function(e){if(!modal.classList.contains('is-open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(index-1);if(e.key==='ArrowRight')show(index+1)});
modal.addEventListener('touchstart',function(e){touchX=e.changedTouches[0].screenX},{passive:true});modal.addEventListener('touchend',function(e){var delta=e.changedTouches[0].screenX-touchX;if(Math.abs(delta)>45)show(index+(delta<0?1:-1))},{passive:true});
})();
</script></body></html>